function safeParseJson(text) {
  if (!text) return null;
  let cleaned = String(text).trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  try { return JSON.parse(cleaned); } catch (e) {
    const firstBrace = cleaned.indexOf('{');
    const lastBrace = cleaned.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      try { return JSON.parse(cleaned.slice(firstBrace, lastBrace + 1)); } catch (e2) { return null; }
    }
    return null;
  }
}

const generatorResp = $('Generador Turn 2').item.json;
const validatorResp = $('Validador Turn 2').item.json;

const generation = safeParseJson(generatorResp && generatorResp.content && generatorResp.content[0] && generatorResp.content[0].text) || {};
const validation = safeParseJson(validatorResp && validatorResp.content && validatorResp.content[0] && validatorResp.content[0].text) || {};

if (!Array.isArray(validation.errores_criticos)) validation.errores_criticos = [];
if (!Array.isArray(validation.razones_fallo)) validation.razones_fallo = [];

const usageGenerator = (generatorResp && generatorResp.usage) || {};
const usageValidator = (validatorResp && validatorResp.usage) || {};

const tokensTotal =
  (usageGenerator.input_tokens || 0) + (usageGenerator.output_tokens || 0) +
  (usageValidator.input_tokens || 0) + (usageValidator.output_tokens || 0);

return [{
  json: {
    generation: generation,
    validation: validation,
    generation_metadata: {
      modelo: (generatorResp && generatorResp.model) || null,
      situacion_detectada: generation.situacion_detectada || null,
      hora_propuesta: generation.hora_propuesta || null,
      transferir_a_sdr: generation.transferir_a_sdr || false,
      notas: generation.notas || null,
      tokens: usageGenerator
    },
    models: {
      generador: (generatorResp && generatorResp.model) || null,
      validador: (validatorResp && validatorResp.model) || null
    },
    tokens_total: tokensTotal
  }
}];

// Index prompts segment-aware.
// Lee el segmento del lead desde Load previous turn y elige la version
// del prompt correspondiente al segmento. Si no hay version segment-specific,
// fallback a MEGA. Si tampoco hay MEGA, deja la key vacia (Anthropic node fallara
// con error claro).

const promptRows = $items().map(i => i.json);
const segmentRaw = ($('Load previous turn').first()?.json?.properties?.gtm__avatar_segment)
                || ($('Load previous turn').first()?.json?.segmento)
                || 'MEGA';
const segment = String(segmentRaw).trim() || 'MEGA';

const indexed = {};
indexed._segment_used = segment;
indexed._fallback_used = false;

// Tipos relevantes para este turn_type
const PROMPT_TYPES = ['classifier', 'generator', 'validator'];

for (const ptype of PROMPT_TYPES) {
  const specific = promptRows.find(r => r.prompt_type === ptype && r.segmento === segment && r.is_active === true && r.turn_type === 'turn2_generic');
  const mega = promptRows.find(r => r.prompt_type === ptype && r.segmento === 'MEGA' && r.is_active === true && r.turn_type === 'turn2_generic');
  const chosen = specific || mega;
  if (chosen) {
    indexed[ptype] = {
      id: chosen.id,
      version: chosen.version,
      prompt_system: chosen.prompt_system,
      model: chosen.model,
      temperature: typeof chosen.temperature === 'number' ? chosen.temperature : 0,
      max_tokens: chosen.max_tokens || 2048,
      _used_segment: chosen.segmento,
    };
    if (!specific && mega) indexed._fallback_used = true;
  }
}

return [{ json: indexed }];

// Calcula el próximo turn_number dinámicamente.
// El WF[01] enruta CUALQUIER subsequent reply (2ª, 3ª, 4ª...) a este WF02b.
// Lee el MAX(turn_number) actual del lead y devuelve +1, garantizando
// unicidad bajo el constraint UNIQUE(smartlead_lead_id, turn_number).

const slLeadId = $('When Executed by Another Workflow').first().json.body.sl_email_lead_id;
// n8n Code node NO expone URLSearchParams. Construimos el query string a mano
// con encodeURIComponent para los valores.
const qs =
  'smartlead_lead_id=eq.' + encodeURIComponent(slLeadId) +
  '&select=turn_number' +
  '&order=turn_number.desc.nullslast' +
  '&limit=1';
const url = 'https://mazhrnqztnjvppgbltuq.supabase.co/rest/v1/cl001_p007_turn1_pipeline?' + qs;

let nextTurn = 2; // fallback seguro
try {
  const resp = await this.helpers.httpRequestWithAuthentication.call(
    this, 'supabaseApi',
    { method: 'GET', url: url, json: true }
  );
  if (Array.isArray(resp) && resp.length > 0) {
    const maxTurn = Number(resp[0].turn_number) || 1;
    nextTurn = maxTurn + 1;
  }
} catch (e) {
  // fallback nextTurn=2 si falla
}
const passthrough = $input.first().json;
return [{ json: Object.assign({}, passthrough, { _next_turn_number: nextTurn }) }];
